import{_ as c,D as n,o as r,c as t,m as l,a as i,G as a,S as D}from"./chunks/framework.DuIEtbrD.js";const g=JSON.parse('{"title":"手摸手实战前端项目CICD","description":"本文从零实现前端项目通过Gitlab、docker、k8s自动化打包部署的真实过程","frontmatter":{"title":"手摸手实战前端项目CICD","description":"本文从零实现前端项目通过Gitlab、docker、k8s自动化打包部署的真实过程","keywords":"docker,k8s,gitlab,gitlab流水线,流水线,CI/CD,自动化构建","logo":"https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/icon-gitlab.png"},"headers":[],"relativePath":"fullstack/gitlab/fe-cicd.md","filePath":"fullstack/gitlab/fe-cicd.md","lastUpdated":1776945570000}'),F={name:"fullstack/gitlab/fe-cicd.md"};function y(b,s,u,m,d,C){const p=n("Obsolete"),e=n("Reward"),o=n("Gitalk");return r(),t("div",null,[s[0]||(s[0]=l("h1",{id:"手摸手实战前端项目ci-cd",tabindex:"-1"},[i("手摸手实战前端项目CI CD "),l("a",{class:"header-anchor",href:"#手摸手实战前端项目ci-cd","aria-label":'Permalink to "手摸手实战前端项目CI CD"'},"​")],-1)),a(p,{date:"2022-12-27"}),s[1]||(s[1]=D(`<p>CI/CD 是 持续集成（Continuous Integration） 和 持续交付/部署（Continuous Delivery/Continuous Deployment） 的缩写，是现代软件开发中的一种自动化方法论，用于加速代码交付和部署的流程，同时保证代码质量和稳定性</p><p>大家工作中应该也都接触到了它的方便，如：提交MR、自动打包、自动部署等等，让开发者大大省去了大量的部署时间，从而专注于需求的开发（纯牛马）</p><p>那么时间久了你是否对这种方法有过思考，如：这一系列是如何运作的、自己如何搭建尝试呢？对于每位开发者来说都有必要尝试去搭建完整的体系，这样自己对软件落地的整体体系会有更明确的认知。本篇文章将手把手带你完成前端项目从开发到部署的整个过程</p><div class="warning custom-block"><p class="custom-block-title">小贴士</p><p>🎁 文章中涉及到的代码示例你都可以从 <a href="https://github.com/ihengshuai/blog-case/tree/gh-pages/fe-cicd" target="_blank" rel="noreferrer">这里查看</a> ，若对你有用还望点赞支持；本篇不适合0️⃣基础小白，需要掌握docker、linux、gitlab、k8s、node等相关知识，如果你对这方面的内容还是空白，可以参考我的往期文章</p></div><h2 id="项目准备" tabindex="-1">项目准备 <a class="header-anchor" href="#项目准备" aria-label="Permalink to &quot;项目准备&quot;">​</a></h2><p>首先在代码管理仓库创建一个项目用来存放项目代码(这里以Gitlab为例)，创建<code>fe-cicd</code>： <img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-02_17.01.53.png" alt=""></p><p>接着创建工程项目，并简单写2个页面；这里本人用CLI助手直接用已有的项目模板来作为演示项目，读者也可以直接使用：执行以下命令很快就会创建好空壳项目模板</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 初始化项目</span></span>
<span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> hengshuai create fe-cicd</span></span>
<span class="line"><span style="color:#FFCB6B;">HengShuai</span><span style="color:#C3E88D;"> CLI v0.0.13</span></span>
<span class="line"><span style="color:#89DDFF;">?</span><span style="color:#BABED8;"> 请选择要创建的模板👇  create a vue project</span></span>
<span class="line"><span style="color:#89DDFF;">?</span><span style="color:#BABED8;"> 请选择模板类型👀  vue3 admin skeleton with nestjs</span></span>
<span class="line"><span style="color:#89DDFF;">?</span><span style="color:#BABED8;"> 是否需要自动安装依赖❓ No</span></span>
<span class="line"><span style="color:#FFCB6B;">🎉</span><span style="color:#C3E88D;"> Successfully created project fe-cicd.</span></span>
<span class="line"><span style="color:#FFCB6B;">👉</span><span style="color:#C3E88D;"> Get started with the following commands:</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> cd fe-cicd</span></span>
<span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> pnpm install</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>将本地项目推送到代码仓库</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">git</span><span style="color:#C3E88D;"> add .</span></span>
<span class="line"><span style="color:#FFCB6B;">git</span><span style="color:#C3E88D;"> cm -m </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">初始化</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"><span style="color:#FFCB6B;">git</span><span style="color:#C3E88D;"> remote add gitlab http://192.168.10.10/learn/fe-cicd.git</span></span>
<span class="line"><span style="color:#FFCB6B;">git</span><span style="color:#C3E88D;"> push origin dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>以上步骤比较简单，我们搞完后就可以在仓库里看到项目代码了:</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-02_17.14.57.png" alt=""></p><h2 id="打包测试" tabindex="-1">打包测试 <a class="header-anchor" href="#打包测试" aria-label="Permalink to &quot;打包测试&quot;">​</a></h2><p>对于一个新项目在真正部署前一般我们都会在本地执行打包脚本先验证下是否可以跑的通，执行以下命令：</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">pnpm</span><span style="color:#C3E88D;"> run build</span></span>
<span class="line"><span style="color:#FFCB6B;">pnpm</span><span style="color:#C3E88D;"> run start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>查看运行结果：项目正常运行了</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-02_17.09.35.png" alt=""></p><h2 id="ci准备" tabindex="-1">CI准备 <a class="header-anchor" href="#ci准备" aria-label="Permalink to &quot;CI准备&quot;">​</a></h2><p>跑流水线最重要的还是ci的配置脚本，通过ci脚本我们可以精确控制流水线如何执行，因此配置好ci是关键</p><h3 id="注册runner" tabindex="-1">注册Runner <a class="header-anchor" href="#注册runner" aria-label="Permalink to &quot;注册Runner&quot;">​</a></h3><p>在写ci配置前要确保已经准备好了<code>gitlab runner</code>，它主要来执行ci的，如果你对runner还是很陌生话请先参考我的往期文章；这里在项目中已经启用了准备好的runner，使用标签是<code>testing</code>；runner的标签名在注册时就可以确定，建议使用有意义的命名规则</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-03_08.20.36.png" alt=""></p><p>一个项目可以使用的多个runner，在ci中体现就是：每个阶段都可以使用不同的runner，或者同阶段的并行任务使用不同runner也可以加速流程，各位视机器配置自行决定</p><h3 id="编写gitlab-ci" tabindex="-1">编写gitlab ci <a class="header-anchor" href="#编写gitlab-ci" aria-label="Permalink to &quot;编写gitlab ci&quot;">​</a></h3><p>本次项目使用Gitlab CI 进行来执行流水线工作，因此我们在项目根目录下创建新建<code>.gitlab-ci.yml</code></p><div class="warning custom-block"><p class="custom-block-title">温馨提示</p><p>如果你对gitlab ci的配置文件不是很熟悉，可以参考我的往期文章并结合官方文档，本篇以主要流程为主不做很详细的配置介绍</p></div><p>这里我们将流水线分4个阶段：</p><ul><li>install：安装依赖</li><li>build：项目构建</li><li>deploy：项目部署</li><li>notice：消息通知，消息通知又分为成功和失败</li></ul><p>根据以上划分可以简单写出下面这些内容：</p><div class="language-yaml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#F07178;">image</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> node:18-alpine</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F07178;">variables</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  IMAGE_TAG</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> $CI_PROJECT_NAME:$CI_COMMIT_REF_NAME</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F07178;">stages</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">  -</span><span style="color:#C3E88D;"> install_deps</span></span>
<span class="line"><span style="color:#89DDFF;">  -</span><span style="color:#C3E88D;"> build</span></span>
<span class="line"><span style="color:#89DDFF;">  -</span><span style="color:#C3E88D;"> deploy</span></span>
<span class="line"><span style="color:#89DDFF;">  -</span><span style="color:#C3E88D;"> notice</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F07178;">install_dependencies</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  stage</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> install_deps</span></span>
<span class="line"><span style="color:#F07178;">  only</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> dev</span></span>
<span class="line"><span style="color:#F07178;">  tags</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> testing</span></span>
<span class="line"><span style="color:#F07178;">  cache</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">    key</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">      files</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">        -</span><span style="color:#C3E88D;"> pnpm-lock.yaml</span></span>
<span class="line"><span style="color:#F07178;">    paths</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">      -</span><span style="color:#C3E88D;"> node_modules</span></span>
<span class="line"><span style="color:#F07178;">  artifacts</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">    expire_in</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">30</span><span style="color:#89DDFF;">&quot;</span><span style="color:#676E95;font-style:italic;"> #30s</span></span>
<span class="line"><span style="color:#F07178;">    paths</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">      -</span><span style="color:#C3E88D;"> node_modules</span></span>
<span class="line"><span style="color:#F07178;">  script</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;Installing dependencies...&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> sed -i &#39;s/dl-cdn.alpinelinux.org/mirrors.aliyun.com/g&#39; /etc/apk/repositories</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> apk update &amp;&amp; apk add git &amp;&amp; apk add openssh-client</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> npm config set registry https://registry.npmmirror.com/</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> npm install -g pnpm</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> pnpm install</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;Dependencies installed successfully!&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F07178;">build_project</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  stage</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> build</span></span>
<span class="line"><span style="color:#F07178;">  only</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> dev</span></span>
<span class="line"><span style="color:#F07178;">  tags</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> testing</span></span>
<span class="line"><span style="color:#F07178;">  artifacts</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">    expire_in</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">30</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#F07178;">    paths</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">      -</span><span style="color:#C3E88D;"> dist</span></span>
<span class="line"><span style="color:#F07178;">  needs</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> install_dependencies</span></span>
<span class="line"><span style="color:#F07178;">  script</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;Building project...&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> pnpm build</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F07178;">deploy_project</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  stage</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> deploy</span></span>
<span class="line"><span style="color:#F07178;">  only</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> dev</span></span>
<span class="line"><span style="color:#F07178;">  tags</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> testing</span></span>
<span class="line"><span style="color:#F07178;">  needs</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> build_project</span></span>
<span class="line"><span style="color:#F07178;">  script</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;Deploying project...&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;success&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 流水线成功消息</span></span>
<span class="line"><span style="color:#F07178;">notice_success</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  stage</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> notice</span></span>
<span class="line"><span style="color:#F07178;">  only</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> dev</span></span>
<span class="line"><span style="color:#F07178;">  tags</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> testing</span></span>
<span class="line"><span style="color:#F07178;">  needs</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> deploy_project</span></span>
<span class="line"><span style="color:#F07178;">  when</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> on_success</span></span>
<span class="line"><span style="color:#F07178;">  script</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;success&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 流水线失败消息</span></span>
<span class="line"><span style="color:#F07178;">notice_failure</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  stage</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> notice</span></span>
<span class="line"><span style="color:#F07178;">  only</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> dev</span></span>
<span class="line"><span style="color:#F07178;">  tags</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> testing</span></span>
<span class="line"><span style="color:#F07178;">  needs</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> deploy_project</span></span>
<span class="line"><span style="color:#F07178;">  when</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> on_failure</span></span>
<span class="line"><span style="color:#F07178;">  script</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;failure&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br><span class="line-number">62</span><br><span class="line-number">63</span><br><span class="line-number">64</span><br><span class="line-number">65</span><br><span class="line-number">66</span><br><span class="line-number">67</span><br><span class="line-number">68</span><br><span class="line-number">69</span><br><span class="line-number">70</span><br><span class="line-number">71</span><br><span class="line-number">72</span><br><span class="line-number">73</span><br><span class="line-number">74</span><br><span class="line-number">75</span><br><span class="line-number">76</span><br><span class="line-number">77</span><br><span class="line-number">78</span><br><span class="line-number">79</span><br><span class="line-number">80</span><br><span class="line-number">81</span><br><span class="line-number">82</span><br><span class="line-number">83</span><br><span class="line-number">84</span><br><span class="line-number">85</span><br><span class="line-number">86</span><br><span class="line-number">87</span><br><span class="line-number">88</span><br><span class="line-number">89</span><br></div></div><p>以上流水线管道在GitLab上的可视化效果如下：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-02_21.47.24.png" alt=""></p><h3 id="按分支执行" tabindex="-1">按分支执行 <a class="header-anchor" href="#按分支执行" aria-label="Permalink to &quot;按分支执行&quot;">​</a></h3><p>通常项目开发会分为好几个环节如：beta、testing、prod等等，不同环境的可能会有不同的权限，不同环境的runner可能也不一样，因此在ci脚本中就可以真不同环境来区分哪些阶段的流程</p><p>假设以下的消息通知，让它只在dev、testing环境下执行，那么就可以通过<code>only</code>关键字来明确指出：</p><div class="language-yaml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#F07178;">notice_success</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  stage</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> notice</span></span>
<span class="line"><span style="color:#F07178;">  only</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> dev</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> testing</span></span>
<span class="line"><span style="color:#F07178;">  tags</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> testing</span></span>
<span class="line"><span style="color:#F07178;">  script</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;success&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="自动化测试" tabindex="-1">自动化测试 <a class="header-anchor" href="#自动化测试" aria-label="Permalink to &quot;自动化测试&quot;">​</a></h3><p>团队中一般对于基建项目会很严格，出一点错误可能就会影响到成百上千的项目。所以通常都会在发布前做相关的自动化测试保证最基本的测试用例不会受到影响，只有这样才能把握住代码的质量；而在ci中我们也可以把它集成进来，在流水线时通过跑自动化测试根据结果来决定是否可以继续执行下去了</p><p>本次通过<a href="https://cn.vitest.dev/" target="_blank" rel="noreferrer">Vitest</a>来演示单元测试，你可以通过其他的工具(如：<a href="https://jestjs.io/zh-Hans/docs/getting-started" target="_blank" rel="noreferrer">Jest</a>、<a href="https://docs.cypress.io/app/get-started/why-cypress" target="_blank" rel="noreferrer">Cypress</a>)附加测试功能；先创建一个简单的测试用例：</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#676E95;font-style:italic;">// __test__/unit/demo.spec.ts</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#89DDFF;"> {</span><span style="color:#BABED8;"> describe</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;"> expect</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;"> it</span><span style="color:#89DDFF;"> }</span><span style="color:#89DDFF;font-style:italic;"> from</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">vitest</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#82AAFF;">describe</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Test Demo</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> ()</span><span style="color:#C792EA;"> =&gt;</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#82AAFF;">  it</span><span style="color:#F07178;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">should pass</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> ()</span><span style="color:#C792EA;"> =&gt;</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#82AAFF;">    expect</span><span style="color:#F07178;">(</span><span style="color:#FF9CAC;">true</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">toBe</span><span style="color:#F07178;">(</span><span style="color:#FF9CAC;">true</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span><span style="color:#BABED8;">)</span><span style="color:#89DDFF;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>新增测试npm脚本：</p><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">scripts</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#FFCB6B;">test:unit</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">vitest run</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><blockquote><p>读者先在本地运行看能否跑通，避免在ci中增加未知问题</p></blockquote><p>增加测试脚本后，我们需要把它集成到ci中；在ci中增加一个<code>testing</code>阶段用来跑测试用例</p><div class="language-yaml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#F07178;">stages</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">  -</span><span style="color:#C3E88D;"> testing</span><span style="color:#676E95;font-style:italic;"> # 新增测试阶段</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F07178;">testing_project</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  stage</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> testing</span></span>
<span class="line"><span style="color:#F07178;">  tags</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> testing</span></span>
<span class="line"><span style="color:#F07178;">  needs</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> install_dependencies</span></span>
<span class="line"><span style="color:#F07178;">  script</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;Testing project...&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> pnpm run test:unit</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-03_08.56.45.png" alt=""></p><p>以上只是简单的将测试放入了ci管道，如果你对测试数据比较感兴趣，如：代码覆盖率、代码质量等等，可以参考<a href="https://docs.gitlab.com/ee/ci/testing/unit_test_reports.html" target="_blank" rel="noreferrer">Test coverage文档</a>、<a href="https://docs.gitlab.com/ee/ci/testing/code_quality.html" target="_blank" rel="noreferrer">Code quality文档</a></p><h3 id="打包镜像" tabindex="-1">打包镜像 <a class="header-anchor" href="#打包镜像" aria-label="Permalink to &quot;打包镜像&quot;">​</a></h3><p>以上我们就对流水线的上半部分的工作就基本做完了，接下来就是打包应用并发布了，这也是很关键的一个步骤；本篇只做云原生应用的部署，如果你还没有涉及到容器相关的技术，这里不做相关的介绍</p><p>容器最关键的就是镜像，对于应用来说可以通过<code>Dockerfile</code>来创建镜像文件，下面是简单的一个例子：</p><div class="language-dockerfile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#F78C6C;">FROM</span><span style="color:#BABED8;"> node:18.19.0-alpine3.19</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F78C6C;">WORKDIR</span><span style="color:#BABED8;"> /app</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 直接从ci打包阶段拿到产物</span></span>
<span class="line"><span style="color:#F78C6C;">COPY</span><span style="color:#BABED8;"> dist dist</span></span>
<span class="line"><span style="color:#F78C6C;">COPY</span><span style="color:#BABED8;"> node_modules node_modules</span></span>
<span class="line"><span style="color:#F78C6C;">COPY</span><span style="color:#BABED8;"> ecosystem.config.js ecosystem.config.js</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#F78C6C;">RUN</span><span style="color:#BABED8;"> npm install pm2 -g --registry=https://registry.npmmirror.com/</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F78C6C;">ENTRYPOINT</span><span style="color:#BABED8;"> [</span><span style="color:#C3E88D;">&quot;pm2-runtime&quot;</span><span style="color:#BABED8;">, </span><span style="color:#C3E88D;">&quot;start&quot;</span><span style="color:#BABED8;">, </span><span style="color:#C3E88D;">&quot;ecosystem.config.js&quot;</span><span style="color:#BABED8;">, </span><span style="color:#C3E88D;">&quot;--env&quot;</span><span style="color:#BABED8;">, </span><span style="color:#C3E88D;">&quot;production&quot;</span><span style="color:#BABED8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>你可以能对上面的docker镜像文件有疑问❓可能觉得他太少了，最基本的项目打包脚本都没有哪来的构建产物；这里我们可以理解为在流水线的流程中在打包阶段将产物保存，然后在构建镜像时直接用就行而不需要在docker中再次构建，这样就省去了大量的时间（更过可以参考gitlab官方文档）</p><p>当然docker最终跑的脚本是通过<a href="https://pm2.keymetrics.io/docs/usage/quick-start/" target="_blank" rel="noreferrer">pm2</a>来维护的，我们还需要编写个pm2的配置文件：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#676E95;font-style:italic;">// https://pm2.keymetrics.io/docs/usage/quick-start/</span></span>
<span class="line"><span style="color:#89DDFF;">module.exports</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#F07178;">  apps</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> [</span></span>
<span class="line"><span style="color:#89DDFF;">    {</span></span>
<span class="line"><span style="color:#F07178;">      name</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">fe-cicd</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#F07178;">      script</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">dist/server/main.js</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#F07178;">      watch</span><span style="color:#89DDFF;">:</span><span style="color:#FF9CAC;"> false</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#F07178;">      instance</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 2</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#F07178;">      autorestart</span><span style="color:#89DDFF;">:</span><span style="color:#FF9CAC;"> true</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#F07178;">      max_memory_restart</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">1G</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#F07178;">      env</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#F07178;">        NODE_ENV</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">development</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">      },</span></span>
<span class="line"><span style="color:#F07178;">      env_production</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#F07178;">        NODE_ENV</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">production</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">      },</span></span>
<span class="line"><span style="color:#89DDFF;">    },</span></span>
<span class="line"><span style="color:#BABED8;">  ]</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><p>这里使用<a href="https://github.com/GoogleContainerTools/kaniko" target="_blank" rel="noreferrer">kaniko</a>来构建镜像：</p><div class="language-yaml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#F07178;">build_image</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  stage</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> build</span></span>
<span class="line"><span style="color:#F07178;">  needs</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> build_project</span></span>
<span class="line"><span style="color:#F07178;">  image</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">    name</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> gcr.io/kaniko-project/executor:debug</span></span>
<span class="line"><span style="color:#F07178;">    entrypoint</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> [</span><span style="color:#89DDFF;">&quot;&quot;</span><span style="color:#89DDFF;">]</span></span>
<span class="line"><span style="color:#F07178;">  only</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> dev</span></span>
<span class="line"><span style="color:#F07178;">  tags</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> testing</span></span>
<span class="line"><span style="color:#F07178;">  script</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;Deploying project...&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> for var in \${PROJECT_ENV_VARIABLE// / }; do echo $var &gt;&gt; .env;done</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> mkdir -p /kaniko/.docker</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;{\\&quot;auths\\&quot;:{\\&quot;\${DOCKER_REPO}\\&quot;:{\\&quot;username\\&quot;:\\&quot;\${DOCKER_REGISTRY_USER}\\&quot;,\\&quot;password\\&quot;:\\&quot;\${DOCKER_REGISTRY_PASSWORD}\\&quot;}}}&quot; &gt; /kaniko/.docker/config.json</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> /kaniko/executor</span></span>
<span class="line"><span style="color:#C3E88D;">      --context &quot;\${CI_PROJECT_DIR}&quot;</span></span>
<span class="line"><span style="color:#C3E88D;">      --dockerfile &quot;\${CI_PROJECT_DIR}/Dockerfile&quot;</span></span>
<span class="line"><span style="color:#C3E88D;">      --destination &quot;$DOCKER_REPO/$IMAGE_TAG&quot;</span></span>
<span class="line"><span style="color:#F07178;">  rules</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#F07178;"> if</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> $CI_COMMIT_TAG</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br></div></div><p>以上构建镜像后会把它推送到容器的仓库中心，细心的读者已经发现我们在，我们在<code>build</code>阶段新增了镜像的构建，因此以下为整体的流程呈现效果</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-03_09.37.00.png" alt=""></p><h3 id="部署应用" tabindex="-1">部署应用 <a class="header-anchor" href="#部署应用" aria-label="Permalink to &quot;部署应用&quot;">​</a></h3><p>在流水线中docker镜像构建好后，就可以把镜像推到镜像仓库了（通常公司都会有自己的私有仓库），然后通过<a href="https://kubernetes.io/" target="_blank" rel="noreferrer">k8s</a>拉取最新镜像自动部署了，这就是部署的基本流程</p><div class="language-yaml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#F07178;">deploy_to_k8s</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  stage</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> deploy</span></span>
<span class="line"><span style="color:#F07178;">  image</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> bitnami/kubectl:latest</span></span>
<span class="line"><span style="color:#F07178;">  only</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> dev</span></span>
<span class="line"><span style="color:#F07178;">  tags</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> testing</span></span>
<span class="line"><span style="color:#F07178;">  needs</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> build_image</span></span>
<span class="line"><span style="color:#F07178;">  before_script</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;Setting up kubectl&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> mkdir -p ~/.kube</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;$KUBE_CONFIG&quot; &gt; ~/.kube/config</span></span>
<span class="line"><span style="color:#F07178;">  script</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;Updating Kubernetes deployment&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> kubectl set image deployment/$K8S_DEPLOYMENT_NAME $K8S_CONTAINER_NAME=$CI_REGISTRY_IMAGE:$CI_COMMIT_SHORT_SHA --namespace=$K8S_NAMESPACE</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> kubectl rollout status deployment/$K8S_DEPLOYMENT_NAME --namespace=$K8S_NAMESPACE</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><h3 id="消息通知" tabindex="-1">消息通知 <a class="header-anchor" href="#消息通知" aria-label="Permalink to &quot;消息通知&quot;">​</a></h3><p>等k8s镜像部署阶段完成后代表整个流程就结束了，因此我们可以在流水线的尾部在增加一个通知阶段，通过发送具体的消息来来告知我们的开发人员，当然流水线的执行状态有<code>成功</code>和<code>失败</code>2中状态，根据不同的状态来告知</p><p>你可以通过HTTP请求将信息发送到消息服务中心，消息中心可以集成到公司用到的应用，这样就会一触即达</p><p>消息通知阶段的流水线以上已经展示过了，这里就不再写了，稍微补充下用到的基础镜像：</p><div class="language-yaml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#F07178;">notice_success</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  # 通过curl来发送消息</span></span>
<span class="line"><span style="color:#F07178;">  image</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> curlimages/curl:7.80.0</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  # 以下内容自行发挥</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="执行机制" tabindex="-1">执行机制 <a class="header-anchor" href="#执行机制" aria-label="Permalink to &quot;执行机制&quot;">​</a></h3><p>通常流水线的执行时机都是通过固定的事件触发的，如：分支合并、分支push等等，而对于重要的环境往往需要手动来降低风险，或者说可以更好的决定执行时机；对于一个复杂应用的发布，可能会涉及到很多基础服务的发布，那么对于自动化发布来说会很麻烦，这里简单提一下如何修改执行时机</p><div class="language-yaml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#F07178;">deploy-job</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  stage</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> deploy</span></span>
<span class="line"><span style="color:#F07178;">  script</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> echo &quot;Deploying the application&quot;</span></span>
<span class="line"><span style="color:#F07178;">  when</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> manual</span><span style="color:#676E95;font-style:italic;">   # 配置为手动触发</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><blockquote><p>在往期的文章中都有关于执行时机的介绍，这里只是提醒下如何更好的实践</p></blockquote><h2 id="心跳检测" tabindex="-1">心跳检测 <a class="header-anchor" href="#心跳检测" aria-label="Permalink to &quot;心跳检测&quot;">​</a></h2><p>大多数的应用都会面对很多问题，如：负载、故障等等；而稳定的应用都会有很多监控措施，对于镜像如何检测它是否正常运行呢，最简单的就是通过写一个检测接口，通过一定的频率来调用，根据响应来判断是否正常，这样在镜像拉胯时，可以重新部署</p><p>下面我们用NodeJS简单写了一个接口<code>/common/health-check</code>：</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">Controller</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/common</span><span style="color:#89DDFF;">&quot;</span><span style="color:#BABED8;">)</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">export</span><span style="color:#C792EA;"> class</span><span style="color:#FFCB6B;"> CommonController</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">	// 心跳检测</span></span>
<span class="line"><span style="color:#89DDFF;">  @</span><span style="color:#82AAFF;">Get</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/health-check</span><span style="color:#89DDFF;">&quot;</span><span style="color:#BABED8;">)</span></span>
<span class="line"><span style="color:#F07178;">  healthCheck</span><span style="color:#89DDFF;">()</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">    return</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">ok</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>接着在k8s pod配置文件中添加心跳检测</p><div class="language-yaml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#F07178;">apiVersion</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> v1</span></span>
<span class="line"><span style="color:#F07178;">kind</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> Pod</span></span>
<span class="line"><span style="color:#F07178;">metadata</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  labels</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">    test</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> liveness</span></span>
<span class="line"><span style="color:#F07178;">  name</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> liveness-http</span></span>
<span class="line"><span style="color:#F07178;">spec</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  containers</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">  -</span><span style="color:#F07178;"> name</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> liveness</span></span>
<span class="line"><span style="color:#F07178;">    image</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> registry.k8s.io/e2e-test-images/agnhost:2.40</span></span>
<span class="line"><span style="color:#F07178;">    args</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;">    -</span><span style="color:#C3E88D;"> liveness</span></span>
<span class="line"><span style="color:#F07178;">    livenessProbe</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">      httpGet</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">        path</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> /common/health-check</span></span>
<span class="line"><span style="color:#F07178;">        port</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 8080</span></span>
<span class="line"><span style="color:#F07178;">      initialDelaySeconds</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 3</span></span>
<span class="line"><span style="color:#F07178;">      periodSeconds</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p>更多玩法请参考<a href="https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/" target="_blank" rel="noreferrer">探针检测</a></p><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><p>纯静态前端项目，大部分会配合nginx使用，这里不做演示</p><p>线上的应用运行效果如何(内存、负载、响应等等)，通常都会在相关的监控后台查看，可以参考k8s可视化资源监控，也可以根据api自行设计监控后台</p>`,80)),a(e),a(o)])}const E=c(F,[["render",y]]);export{g as __pageData,E as default};
